
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_k_csk1_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_k_csk1", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([3.296967063185114e+01, 3.556190027500951e+01, 3.839401508856348e+01, 4.104383743654442e+01, 4.282713182729228e+01, 4.292647663067923e+01, 4.074831033842663e+01, 3.640103002072154e+01, 3.087276622692154e+01, 2.527503045387589e+01, 1.873335548493083e+01, 5.842593045420461e+00, 1.441552884919703e+00, 1.319133308092901e+00, 1.125266719034893e+00, 9.296010632644522e-01, 8.330429365822607e-01, 7.901147291166705e-01, 7.696551572394421e-01, 7.603885974794720e-01]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


